import json

import pandas as pd


def monthly_revenue(json_text: str) -> dict:
    """
    Parse a JSON array of objects with keys "date" and "amount", and return a dict
    mapping "YYYY-MM" to the float total of amounts for each calendar month from the
    earliest to the latest month present, including missing months with 0.0.

    Keys are returned in chronological order.
    """
    if not isinstance(json_text, str):
        raise TypeError("json_text must be a str")

    data = json.loads(json_text)
    if not isinstance(data, list):
        raise ValueError("expected a JSON array")

    if not data:
        return {}

    df = pd.DataFrame(data)

    if "date" not in df.columns or "amount" not in df.columns:
        raise ValueError('each object must contain "date" and "amount" keys')

    dates = pd.to_datetime(df["date"], errors="coerce")
    amounts = pd.to_numeric(df["amount"], errors="coerce")

    valid = dates.notna()
    if not valid.any():
        return {}

    s = pd.Series(amounts.fillna(0.0).to_numpy(dtype=float), index=dates.to_numpy())
    monthly = s.groupby(pd.Grouper(freq="ME")).sum(min_count=1)

    start = dates[valid].min()
    end = dates[valid].max()
    full_idx = pd.date_range(start=start, end=end, freq="ME")
    monthly = monthly.reindex(full_idx, fill_value=0.0).astype(float)

    return {ts.strftime("%Y-%m"): float(total) for ts, total in monthly.items()}
